import RNA
import random, sys, multiprocessing as mp

target = "....((((..(((((..((((..((((.....))))((((((...))).)))))))((((((.((.((.(((((....)).)))))))(((((.((.((.((....))))))(((((.(((....)).))).)))..)).)))))).))))))))(((.(((.(((.((((....))))))))))((((((((...))).)).))).)))))))"
N = len(target)
pair=[-1]*N
stack=[]
for i,c in enumerate(target):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop(); pair[i]=j; pair[j]=i

def init():
    seq=['A']*N
    for i in range(N):
        if pair[i]>=0 and i<pair[i]:
            seq[i]='G'; seq[pair[i]]='C'
    return ''.join(seq)

def fold(s):
    return RNA.fold(s)[0]

def dist(s):
    return RNA.bp_distance(fold(s), target)

# paired-pair mutation: pick a paired position, change both ends to a complementary pair
COMP={'A':'U','U':'A','G':'C','C':'G'}
PAIRS=['AU','UA','GC','CG','GU','UG']

def mut(s):
    ls=list(s)
    r=random.random()
    if r<0.6 and pair and any(pair[i]>i for i in range(N)):
        # paired mutation: pick a paired position
        i=random.randrange(N)
        while pair[i]<0:
            i=random.randrange(N)
        p=random.choice(PAIRS)
        ls[i]=p[0]; ls[pair[i]]=p[1]
    else:
        # single mutation at unpaired position
        i=random.randrange(N)
        ls[i]=random.choice('ACGU')
    return ''.join(ls)

def sa(start, iters, seed):
    random.seed(seed)
    s=start
    d=dist(s)
    best=s; bd=d
    T=3.0
    for it in range(iters):
        ns=mut(s)
        nd=dist(ns)
        if nd<=d or random.random()<pow(2.718,(d-nd)/max(T,0.01)):
            s=ns; d=nd
        if d<bd:
            best=s; bd=d
            if bd==0: return best,0
        T=max(0.1, T*0.9998)
    return best,bd

def worker(args):
    seed, start = args
    return sa(start, 3000, seed)

if __name__=='__main__':
    start=init()
    bd=dist(start)
    print("init dist",bd, file=sys.stderr); sys.stderr.flush()
    best=start; bd0=bd
    tasks=[(s,start) for s in range(2000)]
    with mp.Pool(processes=min(mp.cpu_count(),200)) as p:
        for r,(cand,cd) in enumerate(p.imap_unordered(worker, tasks, chunksize=4)):
